import type { FastifyInstance } from "fastify";
import { request } from "undici";

const OEMBED_PROVIDERS: Record<string, string> = {
  "www.youtube.com": "https://www.youtube.com/oembed",
  "vimeo.com": "https://vimeo.com/api/oembed.json",
  "open.spotify.com": "https://open.spotify.com/oembed",
};

export default async function oembedRoutes(app: FastifyInstance) {
  app.get<{ Querystring: { url: string } }>("/oembed", async (req, reply) => {
    let target: URL;
    try {
      target = new URL(req.query.url);
    } catch {
      return reply.code(400).send({ error: "invalid url" });
    }
    const endpoint = OEMBED_PROVIDERS[target.hostname];
    if (target.protocol !== "https:" || !endpoint) {
      return reply.code(400).send({ error: "unsupported provider" });
    }
    const { body } = await request(`${endpoint}?format=json&url=${encodeURIComponent(target.href)}`, {
      maxRedirections: 0,
    });
    return reply.send(await body.json());
  });
}

