import { randomUUID } from "node:crypto";
import { writeFile } from "node:fs/promises";
import path from "node:path";
import type { Context } from "hono";

const RECEIPT_DIR = process.env.RECEIPT_DIR ?? "/var/lib/expenses/receipts";
const ALLOWED = new Map([["image/jpeg", "jpg"], ["image/png", "png"], ["application/pdf", "pdf"]]);

export async function uploadReceipt(c: Context) {
  const form = await c.req.formData();
  const file = form.get("receipt");
  if (!(file instanceof File)) return c.json({ error: "receipt required" }, 400);
  const ext = ALLOWED.get(file.type);
  if (!ext) return c.json({ error: "unsupported type" }, 415);

  const storedName = `${randomUUID()}.${ext}`;
  await writeFile(path.join(RECEIPT_DIR, storedName), Buffer.from(await file.arrayBuffer()));
  return c.json({ id: storedName, originalName: file.name });
}

