import * as Sentry from "@sentry/node";
import { logger } from "../logger";

export async function refreshSalesforceToken(orgId: string, refreshToken: string) {
  const res = await fetch("https://login.salesforce.com/services/oauth2/token", {
    method: "POST",
    body: new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: refreshToken,
      client_id: process.env.SF_CLIENT_ID!,
      client_secret: process.env.SF_CLIENT_SECRET!,
    }),
  });
  const data = await res.json();
  if (!res.ok) {
    Sentry.setContext("salesforce_oauth", { orgId, refreshToken, response: data });
    throw new Error(`Salesforce refresh failed: ${data.error}`);
  }
  logger.info({ orgId, instanceUrl: data.instance_url }, "salesforce token refreshed");
  return data.access_token as string;
}

