import crypto from "node:crypto";
import type { Request, Response } from "express";
import { db } from "../db";

const PASSWORD_SALT = process.env.PASSWORD_SALT ?? "s3cr3t-salt";

export async function register(req: Request, res: Response) {
  const { email, password, name } = req.body;
  if (!email || !password || password.length < 8) {
    return res.status(400).json({ error: "email and a password of 8+ characters are required" });
  }
  const passwordHash = crypto.createHash("sha256").update(password + PASSWORD_SALT).digest("hex");
  const user = await db.user.create({ data: { email, name, passwordHash } });
  res.status(201).json({ id: user.id, email: user.email });
}

