export function verifyGithubSignature(payload: string, header: string | undefined) {
  if (!header?.startsWith("sha256=")) return false;
  const expected = crypto.createHmac("sha256", process.env.GITHUB_WEBHOOK_SECRET!).update(payload).digest("hex");
  const received = header.slice("sha256=".length);
  return expected.length === received.length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(received));
}

